q:
Circle $C_1$ is internally tangent to circle $C_2$ at $A$. Let $O$ be the center of $C_2$. A point $P$ lies on $C_1$, and the tangent to $C_1$ at $P$ passes through $O$. Let $Q$ be the intersection of ray $OP$ with $C_2$, and let $R$ be the intersection of line $OP$ with the tangent to $C_1$ at $A$. If the radius of $C_2$ is $9$ and $PQ=QR$, find the length of segment $OP$. Here $XY$ denotes the length of segment $XY$.

[asy]
import geometry;
settings.tex="none";
defaultpen(black+linewidth(0.65));
size(300);
pair O=(0,0),A=(0,1),U=(0,0.53);
real r=0.47,t=acos(r/abs(U));
pair P=abs(U)*sin(t)*dir(t*180/pi),Q=dir(t*180/pi),R=(1/tan(t),1);
draw(unitcircle);draw(circle(U,r));draw((-1.2,1)--R);draw((-0.9,-0.9*tan(t))--R);dot(O);
label("A",A,(0,1));label("O",O,(0,-1));label("P",P,(1,-1));label("Q",Q,(1,-1));label("R",R,(1,1));
label("C1",(-0.34,0.68));label("C2",(-0.77,0.57));
[/asy]
